`timescale 1ns/1ps
// Differential fixtures are generated by test_core.py from ISAInterpreter.
module core_tb;
    reg clk=0;
    always #5 clk = !clk;
    reg reset=1, start=0;
    reg [15:0] step_limit=0;
    reg [7:0] program_length=0;
    reg host_write=0, code_write=0;
    reg [4:0] host_addr=0;
    reg [7:0] host_wdata=0, code_wdata=0;
    reg [8:0] code_addr=0;
    wire [7:0] host_rdata, fault, pc;
    wire [15:0] steps;
    wire done, busy, carry;
    isa_core dut (
        .clk(clk), .reset(reset), .start(start), .step_limit(step_limit),
        .program_length(program_length), .host_write(host_write),
        .host_addr(host_addr), .host_wdata(host_wdata), .host_rdata(host_rdata),
        .code_write(code_write), .code_addr(code_addr), .code_wdata(code_wdata),
        .done(done), .busy(busy), .fault(fault), .steps(steps), .pc(pc), .carry(carry)
    );
    reg [7:0] image [0:1048575];
    reg [4095:0] fixture_path;
    integer count, test_no, base, i, cycles, errors=0;

    task tick;
        begin @(posedge clk); #1; end
    endtask

    initial begin
        if (!$value$plusargs("fixtures=%s", fixture_path)) $fatal(1, "missing +fixtures");
        if (!$value$plusargs("count=%d", count)) $fatal(1, "missing +count");
        $readmemh(fixture_path, image, 0, count*512-1);
        tick;
        tick;
        for (test_no=0; test_no<count; test_no=test_no+1) begin
            base=test_no*512;
            @(negedge clk);
            reset=1;
            tick;
            @(negedge clk);
            reset=0;
            for (i=0; i<384; i=i+1) begin
                code_write=1;
                code_addr=i;
                code_wdata=image[base+40+i];
                tick;
                @(negedge clk);
            end
            code_write=0;
            for (i=0; i<32; i=i+1) begin
                host_write=1;
                host_addr=i;
                host_wdata=image[base+8+i];
                tick;
                @(negedge clk);
            end
            host_write=0;
            program_length=image[base];
            step_limit={image[base+2],image[base+1]};
            start=1;
            tick;
            @(negedge clk);
            start=0;
            // Loader writes must not corrupt a running program or its data.
            host_write=1;
            host_addr=31;
            host_wdata=8'ha5;
            code_write=1;
            code_addr=0;
            code_wdata=8'hff;
            tick;
            @(negedge clk);
            host_write=0;
            code_write=0;
            cycles=0;
            while (!done && cycles<1000000) begin tick; cycles=cycles+1; end
            if (!done || busy || fault !== image[base+3] ||
                steps !== {image[base+5],image[base+4]} ||
                pc !== image[base+6] || carry !== image[base+7][0]) begin
                $display("FAIL case %0d status done=%b busy=%b fault=%0d steps=%0d pc=%0d carry=%b expected=%0d/%0d/%0d/%b",
                    test_no,done,busy,fault,steps,pc,carry,image[base+3],
                    {image[base+5],image[base+4]},image[base+6],image[base+7][0]);
                errors=errors+1;
            end
            for (i=0; i<32; i=i+1) begin
                @(negedge clk);
                host_addr=i;
                tick;
                tick;
                if (host_rdata !== image[base+424+i]) begin
                    $display("FAIL case %0d memory[%0d]=%h expected %h",test_no,i,host_rdata,image[base+424+i]);
                    errors=errors+1;
                end
            end
            // Completion and diagnostics stay visible while the host reads.
            if (!done || busy || fault !== image[base+3]) begin
                $display("FAIL case %0d completion was not sticky",test_no);
                errors=errors+1;
            end
        end
        if (errors) $fatal(1,"%0d core differential mismatches",errors);
        $display("PASS: %0d core differential cases",count);
        $finish;
    end
endmodule
